      goalPercent: Math.round((clampPercent(stepsList[index], state.stepsGoal) + clampPercent(caloriesList[index], state.caloriesGoal) + clampPercent(standList[index], state.standGoal)) / 3)
    })
  }

  result.push(makeTodayRecord())
  return result
}

