    records.unshift({
      date: formatDayLabel(item.date),
      stepsText: formatNumber(item.steps),
      caloriesText: formatNumber(item.calories),
      heartText: item.avgHeartRate + ' bpm',
      goalText: item.goalPercent + '%'
