  applyFace(faceId) {
    var nextIndex = faceRegistry.getIndex(faceId)
    var face = faceRegistry.getByIndex(nextIndex)
    this.faceIndex = nextIndex
    this.faceName = face.name
    this.faceBackground = face.background
    this.faceAccent = face.accent
    this.faceDots = faceRegistry.makeDots(nextIndex)
    this.syncFaceSwiper()
  },

  syncFaceSwiper() {
    if (!this.isPill || !this.pageReady || !this.$element) {
      return
    }
    var swiper = this.$element('faceSwiper')
    if (swiper && swiper.swipeTo) {
      swiper.swipeTo({ index: this.faceIndex })
    }
  },

  // Fired when the native swiper settles on a new slide (user horizontal swipe).
  onFaceChange(e) {
    var i = e && (e.index !== undefined ? e.index : (e.detail && e.detail.index))
    if (i === undefined || i === null) {
      return
    }
    if (i === this.faceIndex) {
      return
    }
    this.markUserActive('swipe')
    var selectedFace = faceRegistry.getByIndex(i)
    this.applyFace(selectedFace.id)
    watchData.setSelectedFaceId(selectedFace.id)
  },

  openFaceSelect() {
    clearTimeout(this.longPressTimer)
    this.longPressTimer = null
    pageMotion.push(this, router, '/pages/watchface')
  },

  handleNotifyIgnore() {
    notificationManager.dismiss()
  },

  handleNotifyHangup() {
    notificationManager.hangUp()
  },

  handleTouchStart(e) {
    var self = this
    if (!e.touches || !e.touches[0]) {
      return
    }
    var wasSleeping = this.powerSleepVisible
    this.markUserActive('touch')
    if (wasSleeping) {
      return
    }
    this.touchStartX = e.touches[0].pageX
    this.touchStartY = e.touches[0].pageY
    this.touchMoved = false
    clearTimeout(this.longPressTimer)
    this.longPressTimer = setTimeout(function () {
      if (!self.touchMoved) {
        self.openFaceSelect()
      }
    }, 650)
  },

  handleTouchMove(e) {
    if (!e.touches || !e.touches[0]) {
      return
    }
    this.markUserActive('touch-move')
    var dx = Math.abs(e.touches[0].pageX - this.touchStartX)
    var dy = Math.abs(e.touches[0].pageY - this.touchStartY)
    if (dx > 8 || dy > 8) {
      this.touchMoved = true
      clearTimeout(this.longPressTimer)
      this.longPressTimer = null
    }
  },

  handleTouchEnd() {
    this.markUserActive('touch-end')
    clearTimeout(this.longPressTimer)
    this.longPressTimer = null
  },

  handleSwipe(e) {
    this.markUserActive('swipe')
    if (e.direction === 'up') {
      pageMotion.push(this, router, '/pages/applist', 'fromBottom')
    } else if (!this.isPill && (e.direction === 'left' || e.direction === 'right')) {
      var faces = faceRegistry.getAll()
      var step = e.direction === 'left' ? 1 : -1
      var nextIndex = (this.faceIndex + step + faces.length) % faces.length
      this.applyFace(faces[nextIndex].id)
      watchData.setSelectedFaceId(faces[nextIndex].id)
    }
  }
}
</script>

