<script>
import router from '@system.router'
import pageMotion from '../../common/page_motion'
import watchData from '../../common/watch_data'
import screenProfile from '../../common/screen_profile'
import healthSampleService from '../../common/health_sample_service'

function clamp(value, min, max) {
  return Math.max(min, Math.min(max, value))
}

function calcHourlyRange(hourlyData) {
  if (!hourlyData || hourlyData.length === 0) return { min: 0, max: 0 }
  var min = hourlyData[0].min
  var max = hourlyData[0].max
  for (var i = 1; i < hourlyData.length; i++) {
    if (hourlyData[i].min < min) min = hourlyData[i].min
    if (hourlyData[i].max > max) max = hourlyData[i].max
  }
  return { min: min, max: max }
}

function getHeartTrendRange(values) {
  if (!values || !values.length) return { min: 60, max: 100 }
  var min = Number(values[0]) || 70
  var max = min
  for (var i = 1; i < values.length; i++) {
    var value = Number(values[i]) || min
    if (value < min) min = value
    if (value > max) max = value
  }
  if (max - min < 12) {
    var middle = (min + max) / 2
    min = middle - 6
    max = middle + 6
  }
  return { min: min, max: max }
}

function makeHeartBar(value, active, range) {
  var safeValue = clamp(Number(value) || range.min, range.min, range.max)
  var ratio = (safeValue - range.min) / (range.max - range.min)
  return {
    height: Math.round(ratio * 22) + 7,
    color: active ? '#FF375F' : '#7A2436'
  }
}

export default {
  private: {
    currentHR: 88,
    spo2: 97,
    stress: 28,
    dailyMin: 48,
