<script>
import router from "@system.router";
import app from "@system.app";
export default {
	private: {
		date: new Date(),
		year: "",
		month: "",
		list: null,
		height: "50px",
	},

	onInit() {
		this.initList();
		this.getCalendar();
	},

	initList() {
		let list = [];
		for (let i = 0; i < 5; i++) {
			let initArray = new Array(7).fill("x").map((item) => {
				return {
					value: "",
					className: "",
				};
			});
			list.push(initArray);
		}

		this.list = list;
	},
	backClick() {
		app.terminate();
	},

	isToday(yy, mm, dd) {
		const date = new Date();
		const year = date.getFullYear();
		const month = date.getMonth() + 1;
		const day = date.getDate();
		return yy === year && mm === month && dd === day;
	},

	getCalendar() {
		const year = this.date.getFullYear();
		const month = this.date.getMonth();

		// 获取当月第一天为周几
		const firstDay = new Date(year, month, 1).getDay();

		// 获取当月的天数
		const days = new Date(year, month + 1, 0).getDate();

		this.year = year;
		this.month = month + 1;

		// 确定list的行数，设置每一行的高度
		const rows = Math.ceil((days + firstDay) / 7);
		this.updateListRows(rows);
		this.height = 300 / rows + "px";

		/**
		 * 更新日历：
		 * 1. 从当月第一天开始，根据总天数来进行更新
		 * 2. 前面的空白和后面的空白用“”来填充
		 * 3. 样式为“”或者“today”
		 */
		let count = 1;
		for (let i = 0; i < rows; i++) {
			for (let j = 0; j < 7; j++) {
				if (j === 0 || j === 6) {
					this.list[i][j].className = "cell-text-weekend";
				} else {
					this.list[i][j].className = "cell-text-workday";
				}

				if (i === 0 && j < firstDay) {
					this.list[i][j].value = "";
					continue;
				}
				if (count > days) {
					this.list[i][j].value = "";
					continue;
				}

				this.list[i][j].value = count;
				this.list[i][j].id = "" + this.year + this.month + count;

				if (this.isToday(this.year, this.month, count)) {
					this.list[i][j].className = "cell-text-today";
				}

				count += 1;
			}
		}
	},

	updateListRows(rows) {
		while (this.list.length < rows) {
			let initArray = new Array(7).fill("x").map((item) => {
				return {
					value: "",
					className: "",
				};
			});
			this.list.push(initArray);
		}

		while (this.list.length > rows) {
			this.list.pop();
		}
	},

	prevMonth() {
		this.date = new Date(this.year, this.month - 1, 0);
		this.getCalendar();
	},

	nextMonth() {
		this.date = new Date(this.year, this.month + 1, 0);
		this.getCalendar();
	},

	handleClick(item) {
		if (item.value === "") return;
		router.push({
			uri: "pages/detail",
			params: {
				year: this.year,
				month: this.month,
				day: item.value,
			},
		});
	},

	handleSwipe(eve) {
		if (eve.direction === "left") {
			this.nextMonth();
		} else if (eve.direction === "right") {
			this.prevMonth();
		}
	},
};
</script>

