		this.volume = audio.volume * 100;
	},

	changeVolume(dir) {
		if (dir === -1) {
			if (this.volume < 10) {
				this.volume = 0;
			} else {
				this.volume -= 10;
			}
		} else {
			if (this.volume > 90) {
				this.volume = 100;
			} else {
				this.volume += 10;
			}
		}
		audio.volume = this.volume / 100;
	},

