<script>
import router from '@system.router'
import pageMotion from '../../common/page_motion'
import launcherApps from '../../common/launcher_apps'
import screenProfile from '../../common/screen_profile'

var VIEW_CENTER = 96
var ICON_RADIUS = 21
var MIN_PAN_X = -56
var MAX_PAN_X = 56
var MIN_PAN_Y = -48
var MAX_PAN_Y = 96

function clamp(value, min, max) {
  if (value < min) return min
  if (value > max) return max
  return value
}

function applyResistance(value, min, max) {
  if (value < min) return min + (value - min) * 0.35
  if (value > max) return max + (value - max) * 0.35
  return value
}

export default {
  private: {
    isCircle: false,
    profileReady: false,
    viewportClass: '',
    viewportPosition: 'relative',
    viewportLeft: '0px',
    viewportWidth: '100%',
    viewportHeight: '100%',
    pillApps: launcherApps.createPillApps(),
    circleApps: [],
    focusedLabel: '琛ㄧ洏',
    pageOpacity: 1,
    pageOffset: 0,
    pageOffsetY: 0,
    panX: 0,
    panY: 48
  },

  onInit() {
    var self = this
    screenProfile.resolve(this, function (profile) {
      self.isCircle = profile.isCircle
      self.viewportClass = profile.viewportClass
      self.viewportPosition = profile.viewportPosition
      self.viewportLeft = profile.viewportLeft
      self.viewportWidth = profile.viewportWidth
      self.viewportHeight = profile.viewportHeight
      self.profileReady = true
      if (self.isCircle) {
        self.circleApps = launcherApps.createCircleApps()
        self.updateHoneycomb()
      }
    })
  },

  onShow() {
    pageMotion.enter(this)
    if (this.profileReady && this.isCircle) {
      this.updateHoneycomb()
    }
  },

  onHide() {
    this.stopInertia()
    pageMotion.clear(this)
  },

  onDestroy() {
    this.stopInertia()
    pageMotion.clear(this)
  },

  updateHoneycomb() {
    var nearestDistance = 10000
    var nearestLabel = this.focusedLabel
    var nextApps = []
    for (var index = 0; index < this.circleApps.length; index++) {
      var source = this.circleApps[index]
      var centerX = VIEW_CENTER + source.x + this.panX
      var centerY = VIEW_CENTER + source.y + this.panY
      var offsetX = centerX - VIEW_CENTER
      var offsetY = centerY - VIEW_CENTER
      var distance = Math.sqrt(offsetX * offsetX + offsetY * offsetY)
      var scale = clamp(1.13 - distance / 170, 0.54, 1.13)
      var opacity = clamp(1.08 - distance / 145, 0.2, 1)
      nextApps.push({
        id: source.id,
        label: source.label,
        icon: source.icon,
        route: source.route,
        x: source.x,
        y: source.y,
        left: Math.round(centerX - ICON_RADIUS),
        top: Math.round(centerY - ICON_RADIUS),
        scale: scale.toFixed(2),
        opacity: opacity.toFixed(2)
      })
      if (distance < nearestDistance) {
        nearestDistance = distance
        nearestLabel = source.label
      }
    }
    this.circleApps = nextApps
    this.focusedLabel = nearestLabel
  },

  handleHoneyTouchStart(event) {
    if (!event.touches || !event.touches[0]) return
    this.stopInertia()
    var point = event.touches[0]
    this.touchStartX = point.pageX
    this.touchStartY = point.pageY
    this.lastTouchX = point.pageX
    this.lastTouchY = point.pageY
    this.lastTouchAt = Date.now()
    this.velocityX = 0
    this.velocityY = 0
    this.dragMoved = false
    this.edgeBack = point.pageX < 22
  },

  handleHoneyTouchMove(event) {
    if (!event.touches || !event.touches[0]) return
    var point = event.touches[0]
    var now = Date.now()
    var elapsed = Math.max(1, now - this.lastTouchAt)
    var deltaX = point.pageX - this.lastTouchX
    var deltaY = point.pageY - this.lastTouchY
    var totalX = point.pageX - this.touchStartX
    var totalY = point.pageY - this.touchStartY
    if (Math.abs(totalX) > 4 || Math.abs(totalY) > 4) {
      this.dragMoved = true
    }
    this.panX = applyResistance(this.panX + deltaX, MIN_PAN_X, MAX_PAN_X)
    this.panY = applyResistance(this.panY + deltaY, MIN_PAN_Y, MAX_PAN_Y)
    this.velocityX = deltaX / elapsed
    this.velocityY = deltaY / elapsed
    this.lastTouchX = point.pageX
    this.lastTouchY = point.pageY
    this.lastTouchAt = now
    this.updateHoneycomb()
  },

  handleHoneyTouchEnd(event) {
    var point = event.changedTouches && event.changedTouches[0]
    var totalX = point ? point.pageX - this.touchStartX : 0
    var totalY = point ? point.pageY - this.touchStartY : 0
    if (this.edgeBack && totalX > 38 && Math.abs(totalY) < 32) {
      this.stopInertia()
      pageMotion.back(this, router)
      return
    }
    if (this.dragMoved) {
      this.suppressClickUntil = Date.now() + 180
      this.startInertia()
    } else {
      this.snapIntoBounds()
    }
  },

  startInertia() {
    var self = this
    var velocityX = this.velocityX || 0
    var velocityY = this.velocityY || 0
    this.stopInertia()
    this.inertiaTimer = setInterval(function () {
      self.panX += velocityX * 16
      self.panY += velocityY * 16
      velocityX *= 0.9
      velocityY *= 0.9

      if (self.panX < MIN_PAN_X || self.panX > MAX_PAN_X) velocityX *= 0.72
      if (self.panY < MIN_PAN_Y || self.panY > MAX_PAN_Y) velocityY *= 0.72

      self.panX += (clamp(self.panX, MIN_PAN_X, MAX_PAN_X) - self.panX) * 0.18
      self.panY += (clamp(self.panY, MIN_PAN_Y, MAX_PAN_Y) - self.panY) * 0.18
      self.updateHoneycomb()

      if (Math.abs(velocityX) < 0.01 && Math.abs(velocityY) < 0.01) {
        self.stopInertia()
        self.snapIntoBounds()
      }
    }, 16)
  },

  stopInertia() {
    clearInterval(this.inertiaTimer)
    this.inertiaTimer = null
  },

  snapIntoBounds() {
    this.panX = clamp(this.panX, MIN_PAN_X, MAX_PAN_X)
    this.panY = clamp(this.panY, MIN_PAN_Y, MAX_PAN_Y)
    this.updateHoneycomb()
  },

  openCircleApp(item) {
    if (!item || Date.now() < (this.suppressClickUntil || 0)) return
    this.stopInertia()
    if (!item.route) {
      pageMotion.back(this, router)
      return
    }
    pageMotion.push(this, router, item.route)
  },

  openPillApp(item) {
    if (!item || !item.route) return
    pageMotion.push(this, router, item.route)
  },

  handleSwipe(event) {
    if (this.isCircle) return
    if (event.direction === 'down' || event.direction === 'right') {
      pageMotion.back(this, router)
    }
  }
}
</script>

