export default {
  private: {
    vibrationEnabled: true,
    vibrationLevel: 'medium',
    vibrationLevelText: '中',
    statusText: '开',
    statusColor: '#30D158',
    lightBg: '#1C1C1E',
    mediumBg: '#FF9F0A',
    strongBg: '#1C1C1E',
    lightText: '#8E8E93',
