      </div>
      <text class="pager-button" style="color: {{ nextColor }}" @click="nextPage">›</text>
    </div>
  </div>
</template>

<script>
import router from '@system.router'
import pageMotion from '../../common/page_motion'
import launcherApps from '../../common/launcher_apps'
import fixedPager from '../../common/fixed_pager'
import screenProfile from '../../common/screen_profile'

export default {
  private: {
    isCircle: false,
    profileReady: false,
    viewportClass: '',
    viewportPosition: 'relative',
    viewportLeft: '0px',
    viewportWidth: '100%',
    viewportHeight: '100%',
    allApps: [],
    pageApps: [],
    circleSlots: [],
    focusedLabel: '',
    pageIndex: 0,
    pageText: '1 / 1',
    pageProgress: '100%',
    previousColor: '#3A3A3C',
    nextColor: '#3A3A3C',
    pageOpacity: 1,
    pageOffset: 0,
    pageOffsetY: 0
  },

  onInit() {
    var self = this
    screenProfile.resolve(this, function (profile) {
      self.isCircle = profile.isCircle
      self.viewportClass = profile.viewportClass
      self.viewportPosition = profile.viewportPosition
      self.viewportLeft = profile.viewportLeft
      self.viewportWidth = profile.viewportWidth
      self.viewportHeight = profile.viewportHeight
      self.allApps = self.isCircle ? launcherApps.createCircleApps() : launcherApps.createPillApps()
      self.profileReady = true
      self.refreshPage()
    })
  },

  onShow() {
    pageMotion.enter(this)
    if (this.profileReady) this.refreshPage()
  },

  onHide() {
    pageMotion.clear(this)
  },

  onDestroy() {
    pageMotion.clear(this)
  },

  refreshPage() {
    if (this.isCircle) {
      this.refreshCirclePage()
      return
    }
    var state = fixedPager.build(this.allApps, this.pageIndex, 4)
    this.pageIndex = state.pageIndex
    this.pageApps = state.items
    this.pageText = state.pageText
    this.pageProgress = Math.round((state.pageNumber / state.pageCount) * 100) + '%'
    this.previousColor = state.hasPrevious ? '#0A84FF' : '#3A3A3C'
    this.nextColor = state.hasNext ? '#0A84FF' : '#3A3A3C'
  },

  refreshCirclePage() {
    var count = this.allApps.length
    if (!count) return
    if (this.pageIndex < 0) this.pageIndex = 0
    if (this.pageIndex >= count) this.pageIndex = count - 1
    var positions = [
      { left: 17, top: 4 }, { left: 63, top: 0 }, { left: 109, top: 4 },
      { left: 5, top: 40 }, { left: 53, top: 29 }, { left: 121, top: 40 },
      { left: 17, top: 82 }, { left: 63, top: 86 }, { left: 109, top: 82 }
    ]
    var offsets = [-4, -3, -2, -1, 0, 1, 2, 3, 4]
    var slots = []
    for (var index = 0; index < positions.length; index++) {
      var sourceIndex = (this.pageIndex + offsets[index] + count) % count
      var source = this.allApps[sourceIndex]
      var center = index === 4
      slots.push({
        slotKey: source.id + '-' + index,
        id: source.id,
        label: source.label,
        icon: center ? source.icon : source.softIcon,
        route: source.route,
        sourceIndex: sourceIndex,
        isCenter: center,
        left: positions[index].left,
        top: positions[index].top,
        size: center ? 54 : 34,
        radius: center ? 27 : 17,
        opacity: center ? 1 : 0.52
      })
    }
    this.circleSlots = slots
    this.focusedLabel = this.allApps[this.pageIndex].label
    this.pageText = this.pageIndex + 1 + ' / ' + count
    this.pageProgress = Math.round(((this.pageIndex + 1) / count) * 100) + '%'
    this.previousColor = this.pageIndex > 0 ? '#0A84FF' : '#3A3A3C'
    this.nextColor = this.pageIndex < count - 1 ? '#0A84FF' : '#3A3A3C'
  },

  previousPage() {
    if (this.isCircle) {
      if (this.pageIndex <= 0) return
      this.pageIndex--
      this.refreshCirclePage()
      return
    }
    var state = fixedPager.move(this.allApps, this.pageIndex, 4, -1)
    if (state.pageIndex === this.pageIndex) return
    this.pageIndex = state.pageIndex
    this.refreshPage()
  },

  nextPage() {
    if (this.isCircle) {
      if (this.pageIndex >= this.allApps.length - 1) return
      this.pageIndex++
      this.refreshCirclePage()
      return
    }
    var state = fixedPager.move(this.allApps, this.pageIndex, 4, 1)
    if (state.pageIndex === this.pageIndex) return
    this.pageIndex = state.pageIndex
    this.refreshPage()
  },

  openApp(item) {
    if (!item) return
    if (!item.route) {
      pageMotion.back(this, router)
      return
    }
    pageMotion.push(this, router, item.route)
  },

  focusOrOpenCircleApp(item) {
    if (!item) return
    if (item.isCenter) {
      this.openApp(item)
      return
    }
    this.pageIndex = item.sourceIndex
    this.refreshCirclePage()
  },

  handleSwipe(event) {
    if (!event) return
    if (event.direction === 'left') {
      this.nextPage()
    } else if (event.direction === 'right') {
      if (this.pageIndex > 0) this.previousPage()
      else pageMotion.back(this, router)
    } else if (event.direction === 'down') {
      pageMotion.back(this, router)
    }
  }
}
</script>

