      </div>
      <div class="pattern-item" @click="testTap"><div class="pattern-mark one"><div class="beat"></div></div><div class="pattern-copy"><text class="pattern-name">轻触</text><text class="pattern-desc">单次短反馈</text></div><text class="pattern-arrow">›</text></div>
      <div class="pattern-item" @click="testGoal"><div class="pattern-mark two"><div class="beat"></div><div class="beat"></div></div><div class="pattern-copy"><text class="pattern-name">达标</text><text class="pattern-desc">两次确认反馈</text></div><text class="pattern-arrow">›</text></div>
      <div class="pattern-item" @click="testCountdown"><div class="pattern-mark three"><div class="beat"></div><div class="beat"></div><div class="beat"></div></div><div class="pattern-copy"><text class="pattern-name">倒计时</text><text class="pattern-desc">三次节奏反馈</text></div><text class="pattern-arrow">›</text></div>
