  // Loading is callback-based because the openvela storage API is asynchronous.
  load(callback) {
    storageAdapter.get(SETTINGS_KEY, function (value) {
      cachedSettings = mergeSettings(value)
      if (callback) {
        callback(cloneSettings(cachedSettings))
      }
    })
  },

  save: save,

