    return cloneSettings(cachedSettings)
  },

  getBrightnessValue(value) {
    if (typeof value === 'number' && !isNaN(value)) {
      return Math.max(0, Math.min(255, Math.round(value)))
    }
    return getLegacyBrightnessValue(value)
  },

