<script>
import router from '@system.router'
import battery from '@system.battery'
import brightness from '@system.brightness'
import systemEvent from '@system.event'
import interconnect from '@system.interconnect'
import sensor from '@system.sensor'
import storage from '@system.storage'
import vibrator from '@system.vibrator'
import health from '@service.health'
import pageMotion from '../../../common/page_motion'
import screenProfile from '../../../common/screen_profile'

function capability(id, name, api, available) {
  return {
    id: id,
    name: name,
    api: api,
    status: available ? '鎺ュ彛瀛樺湪' : '涓嶅彲鐢?,
    color: available ? '#30D158' : '#FF453A',
    background: available ? '#123422' : '#3A1517'
  }
}

export default {
  private: {
    deviceFamily: '妫€娴嬩腑',
    screenSize: '--',
    formFactor: '--',
    platformText: '--',
    viewportMode: '--',
    capabilities: [],
    capabilityPage: [],
    pageIndex: 0,
    pageCount: 3,
    pageText: '1 / 3',
    pageProgress: '33%',
    previousColor: '#3A3A3C',
    nextColor: '#0A84FF',
    pageOpacity: 1,
    pageOffset: 0,
    viewportClass: '',
    viewportPosition: 'relative',
    viewportLeft: '0px',
    viewportWidth: '100%',
    viewportHeight: '100%'
  },

  onInit() {
    this.buildCapabilities()
    var self = this
    screenProfile.resolve(this, function (profile) {
      self.viewportClass = profile.viewportClass
      self.viewportPosition = profile.viewportPosition
      self.viewportLeft = profile.viewportLeft
      self.viewportWidth = profile.viewportWidth
      self.viewportHeight = profile.viewportHeight
      self.deviceFamily = profile.deviceFamily
      self.screenSize = profile.screenWidth + ' 脳 ' + profile.screenHeight
      self.formFactor = profile.formFactor
      self.platformText = profile.model + ' / ' + (profile.platformVersionCode || '--')
      self.viewportMode = profile.isBetaPillViewport ? 'beta 鑳跺泭淇' : '鏍囧噯瑙嗗彛'
      self.refreshPage()
    })
  },

  onShow() {
    pageMotion.enter(this)
    this.buildCapabilities()
    this.refreshPage()
  },

  onHide() {
    pageMotion.clear(this)
  },

  onDestroy() {
    pageMotion.clear(this)
  },

  buildCapabilities() {
    this.capabilities = [
      capability('sensor', '鍔犻€熷害璁?, 'subscribeAccelerometer', !!(sensor && sensor.subscribeAccelerometer)),
      capability('health', '鍋ュ悍鏈嶅姟', 'getRecentSamples', !!(health && health.getRecentSamples)),
      capability('haptic', '鑷畾涔夐渿鍔?, 'vibrator.start / stop', !!(vibrator && vibrator.start && vibrator.stop)),
      capability('battery', '鐢垫睜鐘舵€?, 'battery.getStatus', !!(battery && battery.getStatus)),
      capability('brightness', '灞忓箷浜害', 'brightness.setValue', !!(brightness && brightness.setValue)),
      capability('event', '鍏叡浜嬩欢', 'event.subscribe', !!(systemEvent && systemEvent.subscribe)),
      capability('interconnect', '璁惧浜掕仈', 'interconnect.instance', !!(interconnect && interconnect.instance)),
      capability('storage', '鏈湴瀛樺偍', 'storage.get / set', !!(storage && storage.get && storage.set))
    ]
  },

  refreshPage() {
    if (this.pageIndex < 0) this.pageIndex = 0
    if (this.pageIndex >= this.pageCount) this.pageIndex = this.pageCount - 1
    var start = (this.pageIndex - 1) * 4
    this.capabilityPage = this.pageIndex > 0 ? this.capabilities.slice(start, start + 4) : []
    this.pageText = this.pageIndex + 1 + ' / ' + this.pageCount
    this.pageProgress = Math.round(((this.pageIndex + 1) / this.pageCount) * 100) + '%'
    this.previousColor = this.pageIndex > 0 ? '#0A84FF' : '#3A3A3C'
    this.nextColor = this.pageIndex < this.pageCount - 1 ? '#0A84FF' : '#3A3A3C'
  },

  previousPage() {
    if (this.pageIndex <= 0) return
    this.pageIndex--
    this.refreshPage()
  },

  nextPage() {
    if (this.pageIndex >= this.pageCount - 1) return
    this.pageIndex++
    this.refreshPage()
  },

  handleSwipe(event) {
    if (!event) return
    if (event.direction === 'left') this.nextPage()
    else if (event.direction === 'right') {
      if (this.pageIndex > 0) this.previousPage()
      else pageMotion.back(this, router)
    }
  }
}
