import vibrator from '@system.vibrator'

var activeId = -1

var PATTERNS = {
  tap: { label: '轻触', duration: 80, interval: 0, count: 1, fallback: 'short' },
  goal: { label: '达标', duration: 120, interval: 100, count: 2, fallback: 'short' },
  countdown: { label: '倒计时', duration: 100, interval: 250, count: 3, fallback: 'short' },
  alert: { label: '警报', duration: 450, interval: 160, count: 2, fallback: 'long' }
}

function getPattern(name) {
  return PATTERNS[name] || PATTERNS.tap
}

function stop() {
  if (activeId === -1) return false
  try {
    if (vibrator && vibrator.stop) vibrator.stop(activeId)
  } catch (error) {
    console.log('custom vibration stop unavailable')
  }
  activeId = -1
  return true
}

function fallback(pattern, callback) {
  try {
    if (vibrator && vibrator.vibrate) {
      vibrator.vibrate({ mode: pattern.fallback })
      if (callback) callback({ ok: true, custom: false, label: pattern.label })
      return true
    }
  } catch (error) {
    console.log('basic vibration unavailable')
  }
  if (callback) callback({ ok: false, custom: false, label: pattern.label })
  return false
}

function play(name, callback) {
  var pattern = getPattern(name)
  stop()
  try {
    if (vibrator && vibrator.start) {
      vibrator.start({
        duration: pattern.duration,
        interval: pattern.interval,
        count: pattern.count,
        success: function (data) {
          activeId = data && data.id !== undefined ? data.id : -1
          if (callback) callback({ ok: true, custom: true, label: pattern.label })
        },
        fail: function () {
          fallback(pattern, callback)
        }
      })
      return true
    }
  } catch (error) {
    console.log('custom vibration unavailable, use basic mode')
  }
  return fallback(pattern, callback)
}

function getSystemMode() {
  try {
    if (vibrator && vibrator.getSystemDefaultMode) {
      return vibrator.getSystemDefaultMode()
    }
  } catch (error) {
    console.log('system vibration mode unavailable')
  }
  return -1
}

export default {
  play: play,
  stop: stop,
  getSystemMode: getSystemMode,
  supportsCustom: function () {
    return !!(vibrator && vibrator.start && vibrator.stop)
  }
}
