        <image class="circle-icon" style="width: {{ $item.size }}px; height: {{ $item.size }}px; border-radius: {{ $item.radius }}px;" src="{{ $item.icon }}"></image>
      </div>
      <div class="center-label">
        <text class="center-name">{{ focusedLabel }}</text>
      </div>
      <div class="circle-position-track">
        <div class="circle-position-dot" style="top: {{ circleIndicatorTop }}px;"></div>
      </div>
      <text class="circle-gesture-tip">上下滑动</text>
    </stack>

    <div class="pager-row" if="{{ profileReady && !isCircle }}">
      <text class="pager-button" style="color: {{ previousColor }}" @click="previousPage">‹</text>
      <div class="pager-track">
        <div class="pager-fill" style="width: {{ pageProgress }}"></div>
      </div>
      <text class="pager-button" style="color: {{ nextColor }}" @click="nextPage">›</text>
    </div>
  </div>
</template>

<script>
import router from '@system.router'
import pageMotion from '../../common/page_motion'
import launcherApps from '../../common/launcher_apps'
import fixedPager from '../../common/fixed_pager'
import screenProfile from '../../common/screen_profile'

var CIRCLE_DRAG_STEP = 28
var CIRCLE_POSITIONS = [
  { left: 21, top: 15 }, { left: 77, top: 7 }, { left: 133, top: 15 },
  { left: 8, top: 67 }, { left: 67, top: 58 }, { left: 146, top: 67 },
  { left: 21, top: 128 }, { left: 77, top: 137 }, { left: 133, top: 128 }
]
var CIRCLE_OFFSETS = [-4, -3, -2, -1, 0, 1, 2, 3, 4]

function buildCirclePages(apps) {
  var pages = []
  var count = apps.length
  for (var focusIndex = 0; focusIndex < count; focusIndex++) {
    var slots = []
    for (var index = 0; index < CIRCLE_POSITIONS.length; index++) {
      var sourceIndex = (focusIndex + CIRCLE_OFFSETS[index] + count) % count
      var source = apps[sourceIndex]
      var center = index === 4
      slots.push({
        slotKey: focusIndex + '-' + source.id + '-' + index,
        id: source.id,
        label: source.label,
        icon: center ? source.icon : source.softIcon,
        route: source.route,
        sourceIndex: sourceIndex,
        isCenter: center,
        left: CIRCLE_POSITIONS[index].left,
        top: CIRCLE_POSITIONS[index].top,
        size: center ? 58 : 38,
        radius: center ? 29 : 19,
        opacity: center ? 1 : 0.58
      })
    }
    pages.push(slots)
  }
  return pages
}

export default {
  private: {
    isCircle: false,
    profileReady: false,
    viewportClass: '',
    viewportPosition: 'relative',
    viewportLeft: '0px',
    viewportWidth: '100%',
    viewportHeight: '100%',
    viewportTop: '0px',
    allApps: [],
    pageApps: [],
    circleSlots: [],
    circlePages: [],
    focusedLabel: '',
    circleIndicatorTop: 0,
    pageIndex: 0,
    pageText: '1 / 1',
    pageProgress: '100%',
    previousColor: '#3A3A3C',
    nextColor: '#3A3A3C',
    pageOpacity: 1,
    pageOffset: 0,
    pageOffsetY: 0
  },

  onInit() {
    var self = this
    screenProfile.resolve(this, function (profile) {
      self.isCircle = profile.isCircle
      self.viewportClass = profile.viewportClass
      self.viewportPosition = profile.viewportPosition
      self.viewportLeft = profile.viewportLeft
      self.viewportWidth = profile.viewportWidth
      self.viewportHeight = profile.viewportHeight
      self.viewportTop = profile.viewportTop
      self.allApps = self.isCircle ? launcherApps.createCircleApps() : launcherApps.createPillApps()
      if (self.isCircle) self.circlePages = buildCirclePages(self.allApps)
      self.profileReady = true
      self.refreshPage()
    })
  },

  onShow() {
    pageMotion.enter(this)
    if (this.profileReady) this.refreshPage()
  },

  onHide() {
    pageMotion.clear(this)
  },

  onDestroy() {
    pageMotion.clear(this)
  },

  refreshPage() {
    if (this.isCircle) {
      this.refreshCirclePage()
      return
    }
    var state = fixedPager.build(this.allApps, this.pageIndex, 4)
    this.pageIndex = state.pageIndex
    this.pageApps = state.items
    this.pageText = state.pageText
    this.pageProgress = Math.round((state.pageNumber / state.pageCount) * 100) + '%'
    this.previousColor = state.hasPrevious ? '#0A84FF' : '#3A3A3C'
    this.nextColor = state.hasNext ? '#0A84FF' : '#3A3A3C'
  },

  refreshCirclePage() {
    var count = this.allApps.length
    if (!count) return
    if (this.pageIndex < 0) this.pageIndex = 0
    if (this.pageIndex >= count) this.pageIndex = count - 1
    this.circleSlots = this.circlePages[this.pageIndex] || []
    this.focusedLabel = this.allApps[this.pageIndex].label
    this.pageText = this.pageIndex + 1 + ' / ' + count
    this.pageProgress = Math.round(((this.pageIndex + 1) / count) * 100) + '%'
    this.previousColor = this.pageIndex > 0 ? '#0A84FF' : '#3A3A3C'
    this.nextColor = this.pageIndex < count - 1 ? '#0A84FF' : '#3A3A3C'
    this.circleIndicatorTop = count > 1 ? Math.round((this.pageIndex / (count - 1)) * 40) : 0
  },

  moveCircleFocus(step) {
    var count = this.allApps.length
    if (!count) return false
    var now = Date.now()
    if (now - (this.lastCircleMoveAt || 0) < 70) return false
    this.lastCircleMoveAt = now
    this.pageIndex = (this.pageIndex + step + count) % count
    this.refreshCirclePage()
    return true
  },

  previousPage() {
    if (this.isCircle) {
      this.moveCircleFocus(-1)
      return
    }
    var state = fixedPager.move(this.allApps, this.pageIndex, 4, -1)
    if (state.pageIndex === this.pageIndex) return
    this.pageIndex = state.pageIndex
    this.refreshPage()
  },

  nextPage() {
    if (this.isCircle) {
      this.moveCircleFocus(1)
      return
    }
    var state = fixedPager.move(this.allApps, this.pageIndex, 4, 1)
    if (state.pageIndex === this.pageIndex) return
    this.pageIndex = state.pageIndex
    this.refreshPage()
  },

  openApp(item) {
    if (!item) return
    if (!item.route) {
      pageMotion.back(this, router)
      return
    }
    pageMotion.push(this, router, item.route)
  },

  focusOrOpenCircleApp(item) {
    if (!item || Date.now() < (this.suppressCircleClickUntil || 0)) return
    if (item.isCenter) {
      this.openApp(item)
      return
    }
    this.pageIndex = item.sourceIndex
    this.refreshCirclePage()
  },

  handleCircleTouchStart(event) {
    if (!event.touches || !event.touches[0]) return
    var point = event.touches[0]
    this.circleTouchStartX = point.pageX
    this.circleTouchStartY = point.pageY
    this.circleTouchAnchorY = point.pageY
    this.circleTouchAxis = ''
    this.circleDragMoved = false
    this.circleFocusChangedDuringDrag = false
  },

  handleCircleTouchMove(event) {
    if (!event.touches || !event.touches[0]) return
    var point = event.touches[0]
    var totalX = point.pageX - this.circleTouchStartX
    var totalY = point.pageY - this.circleTouchStartY
    if (!this.circleTouchAxis && (Math.abs(totalX) > 7 || Math.abs(totalY) > 7)) {
      this.circleTouchAxis = Math.abs(totalY) > Math.abs(totalX) * 1.1 ? 'vertical' : 'horizontal'
    }
    if (this.circleTouchAxis !== 'vertical') return
    if (Math.abs(totalY) > 10) this.circleDragMoved = true
    var deltaY = point.pageY - this.circleTouchAnchorY
    if (deltaY <= -CIRCLE_DRAG_STEP) {
      if (this.moveCircleFocus(1)) {
        this.circleTouchAnchorY = point.pageY
        this.circleFocusChangedDuringDrag = true
      }
    } else if (deltaY >= CIRCLE_DRAG_STEP) {
      if (this.moveCircleFocus(-1)) {
        this.circleTouchAnchorY = point.pageY
        this.circleFocusChangedDuringDrag = true
      }
    }
  },

  handleCircleTouchEnd(event) {
    var point = event.changedTouches && event.changedTouches[0]
    var totalX = point ? point.pageX - this.circleTouchStartX : 0
    var totalY = point ? point.pageY - this.circleTouchStartY : 0
    if (totalX > 38 && Math.abs(totalY) < 34) {
      this.backFromCircle()
      return
    }
    if (this.circleDragMoved) this.suppressCircleClickUntil = Date.now() + 180
    if (this.circleFocusChangedDuringDrag) this.lastCircleMoveAt = Date.now()
  },

  backFromCircle() {
    var now = Date.now()
    if (now - (this.lastCircleBackAt || 0) < 300) return
    this.lastCircleBackAt = now
    pageMotion.back(this, router)
  },

  handleSwipe(event) {
    if (!event) return
    if (this.isCircle) {
      if (event.direction === 'up') this.nextPage()
      else if (event.direction === 'down') this.previousPage()
      else if (event.direction === 'right') this.backFromCircle()
      return
    }
    if (event.direction === 'left') {
      this.nextPage()
    } else if (event.direction === 'right') {
      if (this.pageIndex > 0) this.previousPage()
      else pageMotion.back(this, router)
    } else if (event.direction === 'down') {
      pageMotion.back(this, router)
    }
  }
}
</script>

