  openFocusedCircleApp() {
    if (this.allApps[this.pageIndex]) this.openApp(this.allApps[this.pageIndex])
  },

  handleCircleTouchStart(event) {
    if (!event.touches || !event.touches[0]) return
    var point = event.touches[0]
    this.circleTouchStartX = point.pageX
    this.circleTouchStartY = point.pageY
    this.circleTouchAnchorY = point.pageY
    this.circleTouchLastY = point.pageY
    this.circleTouchAxis = ''
    this.circleDragMoved = false
    this.circleFocusChangedDuringDrag = false
  },

  handleCircleTouchMove(event) {
    if (!event.touches || !event.touches[0]) return
    var point = event.touches[0]
    var totalX = point.pageX - this.circleTouchStartX
    var totalY = point.pageY - this.circleTouchStartY
    if (!this.circleTouchAxis && (Math.abs(totalX) > 7 || Math.abs(totalY) > 7)) {
      this.circleTouchAxis = Math.abs(totalY) > Math.abs(totalX) * 1.1 ? 'vertical' : 'horizontal'
    }
    if (this.circleTouchAxis !== 'vertical') return
    if (Math.abs(totalY) > 10) this.circleDragMoved = true
    var deltaY = point.pageY - this.circleTouchLastY
    this.circleTouchLastY = point.pageY
    this.circleDragOffset += deltaY
    while (this.circleDragOffset <= -CIRCLE_FOCUS_PITCH) {
      this.circleDragOffset += CIRCLE_FOCUS_PITCH
      this.moveCircleFocus(1, true)
      this.circleFocusChangedDuringDrag = true
    }
    while (this.circleDragOffset >= CIRCLE_FOCUS_PITCH) {
      this.circleDragOffset -= CIRCLE_FOCUS_PITCH
      this.moveCircleFocus(-1, true)
      this.circleFocusChangedDuringDrag = true
    }
    this.updateCircleSlotPositions()
  },

  handleCircleTouchEnd(event) {
    this.lastCircleTouchEndAt = Date.now()
    var point = event.changedTouches && event.changedTouches[0]
    var totalX = point ? point.pageX - this.circleTouchStartX : 0
    var totalY = point ? point.pageY - this.circleTouchStartY : 0
    if (totalX > 38 && Math.abs(totalY) < 34) {
      this.backFromCircle()
      return
    }
    if (this.circleDragMoved) {
      this.suppressCircleClickUntil = Date.now() + 220
      if (this.circleDragOffset <= -CIRCLE_FOCUS_PITCH / 2) this.moveCircleFocus(1, true)
      else if (this.circleDragOffset >= CIRCLE_FOCUS_PITCH / 2) this.moveCircleFocus(-1, true)
      this.circleDragOffset = 0
      this.updateCircleSlotPositions()
    }
  },

  backFromCircle() {
    var now = Date.now()
    if (now - (this.lastCircleBackAt || 0) < 300) return
    this.lastCircleBackAt = now
    pageMotion.back(this, router)
  },

  handleSwipe(event) {
    if (!event) return
    if (this.isCircle) {
      if (Date.now() - (this.lastCircleTouchEndAt || 0) < 260) return
      if (event.direction === 'up') this.nextPage()
      else if (event.direction === 'down') this.previousPage()
      else if (event.direction === 'right') this.backFromCircle()
      return
    }
    if (event.direction === 'left') {
      this.nextPage()
    } else if (event.direction === 'right') {
      if (this.pageIndex > 0) this.previousPage()
      else pageMotion.back(this, router)
    } else if (event.direction === 'down') {
      pageMotion.back(this, router)
    }
  }
