    name: '极简霓虹',
    description: '极简时间和目标圆环',
    background: '#05060A',
    accent: '#00E5FF'
  },
  {
    id: 'dashboard',
    name: '运动仪表',
    description: '集中展示活动和设备状态',
    background: '#080B10',
    accent: '#32D74B'
  },
  {
    id: 'mechanical',
    name: '曜金机械',
    description: '金属刻度、三针和机械副盘',
    background: '#050607',
    accent: '#D6B878',
    circleOnly: true
  }
]

function getAll(includeCircleOnly) {
  if (includeCircleOnly !== false) return FACE_LIST.slice()
  return FACE_LIST.filter(function (face) {
    return !face.circleOnly
  })
}

function getIndex(faceId, includeCircleOnly) {
  var faces = getAll(includeCircleOnly)
  for (var index = 0; index < faces.length; index++) {
    if (faces[index].id === faceId) {
      return index
    }
  }
  return 0
}

function getById(faceId, includeCircleOnly) {
  return getByIndex(getIndex(faceId, includeCircleOnly), includeCircleOnly)
}

function getByIndex(index, includeCircleOnly) {
  var faces = getAll(includeCircleOnly)
  if (index < 0 || index >= faces.length) {
    return faces[0]
  }
  return faces[index]
}

function makeDots(index, includeCircleOnly) {
  var faces = getAll(includeCircleOnly)
  var activeFace = getByIndex(index, includeCircleOnly)
  var dots = []
  for (var dotIndex = 0; dotIndex < faces.length; dotIndex++) {
    dots.push({
      width: dotIndex === index ? 18 : 6,
      color: dotIndex === index ? activeFace.accent : '#3A3A3C'
    })
  }
  return dots
}

export default {
  getAll: getAll,
  getIndex: getIndex,
  getById: getById,
  getByIndex: getByIndex,
  makeDots: makeDots
}

