var api = null
var resolved = false

function resolveApi() {
  if (resolved) return api
  resolved = true
  try {
    api = require('@system.velaclaw')
  } catch (error) {
    api = null
    console.log('velaclaw unavailable on this runtime')
  }
  return api
}

function isAvailable() {
  var current = resolveApi()
  return !!(current && typeof current.ask === 'function')
}

function ask(query, callback) {
  var current = resolveApi()
  if (!current || typeof current.ask !== 'function') {
    callback({ ok: false, code: 203, message: '当前设备未启用 AI Agent' })
    return
  }
  try {
    current.ask({
      query: query,
      success: function (data) {
        callback({ ok: true, reply: data && data.reply ? data.reply : '' })
      },
      fail: function (data, code) {
        callback({ ok: false, code: Number(code) || 1000, message: data || 'AI 服务不可用' })
      },
      complete: function () {}
    })
  } catch (error) {
    callback({ ok: false, code: 1000, message: 'AI 接口调用失败' })
  }
}

export default {
  isAvailable: isAvailable,
  ask: ask
}
